package task

import "time"

func Backoff(attempt int, base time.Duration) time.Duration {
	d := base
	for i := 0; i < attempt; i++ {
		d *= 2
	}
	if d > 10000*time.Millisecond {
		return 10000 * time.Millisecond
	}
	return d
}

func Schedule(c Config) []time.Duration {
	out := make([]time.Duration, c.Attempts)
	for i := range out {
		out[i] = Backoff(i, c.Retry)
	}
	return out
}
EOF
