package task

import "time"

func Deadline(start time.Time, timeout time.Duration) time.Time {
	return start.Add(timeout)
}

func Expired(start, now time.Time, idle time.Duration) bool {
	return now.Sub(start) > idle
}

func Remaining(start, now time.Time, c Config) time.Duration {
	left := Deadline(start, c.Timeout).Sub(now)
	if left < 0 {
		return 0
	}
	return left.Truncate(time.Millisecond)
}
EOF
